-- Lobbies table\ncreate table if not exists lobbies (\n  id uuid primary key default gen_random_uuid(),\n  code varchar(6) not null unique,\n  host_id uuid not null,\n  game_size varchar(20) not null check (game_size in ('small', 'medium', 'large')),\n  created_at timestamp with time zone default now(),\n  started_at timestamp with time zone,\n  finished_at timestamp with time zone\n);\n\n-- Games table\ncreate table if not exists games (\n  id uuid primary key default gen_random_uuid(),\n  lobby_id uuid not null references lobbies(id) on delete cascade,\n  state varchar(50) not null default 'LOBBY' check (state in ('LOBBY', 'HIDE_TIMER', 'ACTIVE_GAME', 'QUESTION_PENDING', 'QUESTION_ANSWERED', 'ENDGAME', 'CAPTURE_ATTEMPT', 'GAME_OVER')),\n  hider_id uuid not null,\n  created_at timestamp with time zone default now(),\n  started_at timestamp with time zone,\n  hide_end_time timestamp with time zone,\n  game_end_time timestamp with time zone,\n  winner varchar(20) check (winner in ('hider', 'seeker'))\n);\n\n-- Players table\ncreate table if not exists players (\n  id uuid primary key default gen_random_uuid(),\n  lobby_id uuid not null references lobbies(id) on delete cascade,\n  game_id uuid references games(id) on delete cascade,\n  role varchar(20) not null check (role in ('hider', 'seeker')),\n  display_name varchar(100) not null,\n  is_active boolean default true,\n  joined_at timestamp with time zone default now()\n);\n\n-- Questions table\ncreate table if not exists questions (\n  id uuid primary key default gen_random_uuid(),\n  category varchar(100) not null,\n  text text not null,\n  response_type varchar(50) not null check (response_type in ('boolean', 'multiple_choice', 'text', 'image')),\n  response_time_seconds integer not null default 60,\n  card_draw_count integer not null default 1,\n  created_at timestamp with time zone default now()\n);\n\n-- Game Questions table (questions asked during a game)\ncreate table if not exists game_questions (\n  id uuid primary key default gen_random_uuid(),\n  game_id uuid not null references games(id) on delete cascade,\n  question_id uuid not null references questions(id),\n  asked_by_id uuid not null references players(id),\n  asked_at timestamp with time zone default now(),\n  answered_at timestamp with time zone,\n  answer text,\n  veto_used boolean default false\n);\n\n-- Cards table\ncreate table if not exists cards (\n  id uuid primary key default gen_random_uuid(),\n  category varchar(50) not null check (category in ('TIME_BONUS', 'POWER_UP', 'CURSE', 'VETO')),\n  effect varchar(255) not null,\n  description text not null,\n  created_at timestamp with time zone default now()\n);\n\n-- Player Hands table\ncreate table if not exists player_hands (\n  id uuid primary key default gen_random_uuid(),\n  player_id uuid not null references players(id) on delete cascade,\n  game_id uuid not null references games(id) on delete cascade,\n  cards uuid[] not null default '{}',\n  updated_at timestamp with time zone default now()\n);\n\n-- Location Pings table\ncreate table if not exists location_pings (\n  id uuid primary key default gen_random_uuid(),\n  player_id uuid not null references players(id) on delete cascade,\n  game_id uuid not null references games(id) on delete cascade,\n  latitude numeric not null,\n  longitude numeric not null,\n  accuracy numeric,\n  timestamp timestamp with time zone default now()\n);\n\n-- Active Effects table\ncreate table if not exists active_effects (\n  id uuid primary key default gen_random_uuid(),\n  player_id uuid not null references players(id) on delete cascade,\n  game_id uuid not null references games(id) on delete cascade,\n  effect_type varchar(100) not null,\n  started_at timestamp with time zone default now(),\n  duration_seconds integer not null\n);\n\n-- Game Events table (event log for realtime)\ncreate table if not exists game_events (\n  id uuid primary key default gen_random_uuid(),\n  game_id uuid not null references games(id) on delete cascade,\n  event_type varchar(100) not null,\n  player_id uuid references players(id),\n  data jsonb not null default '{}',\n  created_at timestamp with time zone default now()\n);\n\n-- Indexes for performance\ncreate index if not exists idx_lobbies_code on lobbies(code);\ncreate index if not exists idx_games_lobby_id on games(lobby_id);\ncreate index if not exists idx_games_hider_id on games(hider_id);\ncreate index if not exists idx_players_lobby_id on players(lobby_id);\ncreate index if not exists idx_players_game_id on players(game_id);\ncreate index if not exists idx_game_questions_game_id on game_questions(game_id);\ncreate index if not exists idx_location_pings_game_id on location_pings(game_id);\ncreate index if not exists idx_location_pings_player_id on location_pings(player_id);\ncreate index if not exists idx_active_effects_game_id on active_effects(game_id);\ncreate index if not exists idx_game_events_game_id on game_events(game_id);\n\n-- Enable realtime on necessary tables\nalter publication supabase_realtime add table game_events;\nalter publication supabase_realtime add table location_pings;\nalter publication supabase_realtime add table games;\nalter publication supabase_realtime add table player_hands;\nalter publication supabase_realtime add table game_questions;\n"